            os.chmod(p, 0o755)
        for name, tool in (("colabfold_batch", "colabfold_batch"), ("lightdock3_setup.py", "lightdock3_setup.py"),
                           ("lightdock3.py", "lightdock3.py"), ("lgd_generate_conformations.py", "lgd_generate_conformations.py"),
